output:
// Функция заполняет табличную часть "Товары" остатками из регистра накопления "ТоварныеЗапасы".
// Параметры:
//  ДокументОбъект - ДокументОбъект.Заказ - Объект документа, который необходимо заполнить.
Процедура ЗаполнитьТабличнуюЧастьОстатками(ДокументОбъект) Экспорт

	// Очищаем табличную часть перед заполнением
	ДокументОбъект.Товары.Очистить();

	Запрос = Новый Запрос;
	Запрос.Текст = 
	"ВЫБРАТЬ
	|	ТоварныеЗапасыОстатки.Товар КАК Товар,
	|	ТоварныеЗапасыОстатки.КоличествоОстаток КАК Количество
	|ИЗ
	|	РегистрНакопления.ТоварныеЗапасы.Остатки(
	|			&Период,
	|			Склад = &Склад
	|				И Товар.ВидТовара = ЗНАЧЕНИЕ(Перечисление.ВидыТоваров.Товар)) КАК ТоварныеЗапасыОстатки";

	// Устанавливаем параметры запроса
	// Если дата документа не заполнена, будет использована текущая дата (неограниченность)
	Запрос.УстановитьПараметр("Период", ДокументОбъект.Дата);
	Запрос.УстановитьПараметр("Склад", ДокументОбъект.Склад);

	РезультатЗапроса = Запрос.Выполнить();

	// Проверка на пустоту результата для оптимизации
	Если РезультатЗапроса.Пустой() Тогда
		Возврат;
	КонецЕсли;

	ВыборкаДетальныеЗаписи = РезультатЗапроса.Выбрать();

	// Заполняем табличную часть документа
	Пока ВыборкаДетальныеЗаписи.Следующий() Цикл
		НоваяСтрока = ДокументОбъект.Товары.Добавить();
		НоваяСтрока.Товар      = ВыборкаДетальныеЗаписи.Товар;
		НоваяСтрока.Количество = ВыборкаДетальныеЗаписи.Количество;

		// При необходимости здесь можно вызвать обработчик пересчета цен/сумм, 
		// если это предусмотрено логикой конфигурации.
	КонецЦикла;

КонецПроцедуры

// Функция заполняет переданный табличный документ данными о задолженности
// Параметры:
//  ТабДокумент - ТабличныйДокумент - куда выводить данные
//  Макет - МакетКомпоновкиДанных или ТабличныйДокумент - макет для формирования
//  Дата - Дата - момент времени, на который получаются остатки
Процедура ЗаполнитьТабличныйДокумент(ТабДокумент, Макет, Дата) Экспорт

	// Очищаем табличный документ перед заполнением
	ТабДокумент.Очистить();

	// Получаем области из макета
	ОбластьШапка  = Макет.ПолучитьОбласть("Шапка");
	ОбластьСтрока = Макет.ПолучитьОбласть("Строка");

	// Выводим шапку
	ТабДокумент.Вывести(ОбластьШапка);

	// Инициализируем запрос для получения остатков из регистра накопления
	Запрос = Новый Запрос;
	Запрос.Текст = 
	"ВЫБРАТЬ
	|	ВзаиморасчетыОстатки.Контрагент КАК Контрагент,
	|	ВзаиморасчетыОстатки.СуммаОстаток КАК Задолженность
	|ИЗ
	|	РегистрНакопления.Взаиморасчеты.Остатки(&Период, ) КАК ВзаиморасчетыОстатки
	|
	|УПОРЯДОЧИТЬ ПО
	|	Контрагент.Наименование";

	// Устанавливаем параметры запроса
	// Используем Границу, чтобы включить движения на саму дату, если это требуется
	Запрос.УстановитьПараметр("Период", Новый Граница(Дата, ВидГраницы.Включая));

	// Выполняем запрос и обходим результат
	РезультатЗапроса = Запрос.Выполнить();
	ВыборкаДетальныеЗаписи = РезультатЗапроса.Выбрать();

	Пока ВыборкаДетальныеЗаписи.Следующий() Цикл
		// Заполняем параметры области из выборки
		ОбластьСтрока.Параметры.Заполнить(ВыборкаДетальныеЗаписи);

		// Выводим заполненную строку в итоговый документ
		ТабДокумент.Вывести(ОбластьСтрока);
	КонецЦикла;

КонецПроцедуры

// Функция устанавливает склад в строках табличной части "Товары"
//
// Параметры:
//  ДокументОбъект - ДокументОбъект - Объект документа, в котором необходимо обновить склад
//
Процедура УстановитьСклад(ДокументОбъект) Экспорт

	// Проверяем наличие реквизита "Склад" в шапке и табличной части "Товары"
	СкладШапки = ДокументОбъект.Склад;

	// Если склад в шапке не заполнен, решение о дальнейших действиях зависит от бизнес-логики.
	// В данном примере устанавливаем даже пустое значение.

	Для Каждого СтрокаТовар Из ДокументОбъект.Товары Цикл

		// Устанавливаем значение поля СкладСтроки
		Если СтрокаТовар.СкладСтроки <> СкладШапки Тогда
			СтрокаТовар.СкладСтроки = СкладШапки;
		КонецЕсли;

	КонецЦикла;

КонецПроцедуры

// Функция удаляет последнюю по времени запись из независимого регистра сведений КурсыВалют
// Параметры:
//  Валюта - СправочникСсылка.Валюты - Валюта, по которой нужно удалить запись
//
Функция УдалитьПоследнююЗапись(Валюта) Экспорт

	Запрос = Новый Запрос;
	Запрос.Текст = 
	"ВЫБРАТЬ ПЕРВЫЕ 1
	|	КурсыВалют.Период КАК Период
	|ИЗ
	|	РегистрСведений.КурсыВалют КАК КурсыВалют
	|ГДЕ
	|	КурсыВалют.Валюта = &Валюта
	|
	|УПОРЯДОЧИТЬ ПО
	|	Период УБЫВ";

	Запрос.УстановитьПараметр("Валюта", Валюта);

	РезультатЗапроса = Запрос.Выполнить();

	Если НЕ РезультатЗапроса.Пустой() Тогда
		Выборка = РезультатЗапроса.Выбрать();
		Выборка.Следующий();

		// Создаем менеджер записи для удаления конкретной записи
		МенеджерЗаписи = РегистрыСведений.КурсыВалют.СоздатьМенеджерЗаписи();
		МенеджерЗаписи.Валюта = Валюта;
		МенеджерЗаписи.Период = Выборка.Период;

		// Пытаемся прочитать запись, чтобы убедиться в ее существовании и заблокировать
		МенеджерЗаписи.Прочитать();

		Если МенеджерЗаписи.Выбран() Тогда
			Попытка
				МенеджерЗаписи.Удалить();
				Возврат Истина;
			Исключение
				// Обработка ошибки блокировки или прав доступа
				ЗаписьЖурналаРегистрации("УдалениеЗаписиКурса", УровеньЖурналаРегистрации.Ошибка, , , ОписаниеОшибки());
				Возврат Ложь;
			КонецПопытки;
		КонецЕсли;
	КонецЕсли;

	Возврат Ложь;

КонецФункции

// Функция возвращает список товаров указанного поставщика, 
// для которых не установлены цены в регистре "ЦеныТоваров".
//
// Параметры:
//  Поставщик - СправочникСсылка.Контрагенты (или иной тип, используемый в справочнике Товары)
//
// Возвращаемое значение:
//  СписокЗначений - список товаров без установленных цен.
Функция НеУстановленыЦены(Поставщик) Экспорт

	Запрос = Новый Запрос;
	Запрос.Текст = 
	"ВЫБРАТЬ
	|	Товары.Ссылка КАК Товар
	|ИЗ
	|	Справочник.Товары КАК Товары
	|		ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.ЦеныТоваров.СрезПоследних КАК ЦеныТоваровСрезПоследних
	|		ПО Товары.Ссылка = ЦеныТоваровСрезПоследних.Товар
	|ГДЕ
	|	Товары.Поставщик = &Поставщик
	|	И ЦеныТоваровСрезПоследних.Товар ЕСТЬ NULL";

	Запрос.УстановитьПараметр("Поставщик", Поставщик);

	РезультатЗапроса = Запрос.Выполнить();

	СписокТоваров = Новый СписокЗначений;

	Если Не РезультатЗапроса.Пустой() Тогда
		ВыборкаДетальныеЗаписи = РезультатЗапроса.Выбрать();

		Пока ВыборкаДетальныеЗаписи.Следующий() Цикл
			СписокТоваров.Добавить(ВыборкаДетальныеЗаписи.Товар);
		КонецЦикла;
	КонецЕсли;

	Возврат СписокТоваров;

КонецФункции

// Функция выгружает остатки товаров по конкретному складу в файл JSON.
// Параметры:
//  Склад - СправочникСсылка.Склады
//  МинимальныйОстаток - Число
//  ФайлJson - Строка (путь к файлу)
//
Функция ВыгрузитьОстаткиСклада(Склад, МинимальныйОстаток, ФайлJson) Экспорт

	Запрос = Новый Запрос;
	Запрос.Текст = 
	"ВЫБРАТЬ
	|	ТоварныеЗапасыОстатки.Товар.Код КАК Товар_Код,
	|	ТоварныеЗапасыОстатки.Товар.Наименование КАК Товар_Наименование,
	|	ВЫРАЗИТЬ(ТоварныеЗапасыОстатки.КоличествоОстаток КАК ЧИСЛО(15, 0)) КАК Остаток
	|ИЗ
	|	РегистрНакопления.ТоварныеЗапасы.Остатки(&Период, Склад = &Склад) КАК ТоварныеЗапасыОстатки
	|ГДЕ
	|	ТоварныеЗапасыОстатки.КоличествоОстаток >= &МинимальныйОстаток
	|
	|УПОРЯДОЧИТЬ ПО
	|	Товар_Код";

	Запрос.УстановитьПараметр("Склад", Склад);
	Запрос.УстановитьПараметр("МинимальныйОстаток", МинимальныйОстаток);
	Запрос.УстановитьПараметр("Период", ТекущаяДата());

	РезультатЗапроса = Запрос.Выполнить();

	// Подготовка данных для JSON
	СписокДанных = Новый Массив;
	Выборка = РезультатЗапроса.Выбрать();

	Пока Выборка.Следующий() Цикл
		СтруктураСтроки = Новый Структура;
		СтруктураСтроки.Вставить("Товар_Код",          Выборка.Товар_Код);
		СтруктураСтроки.Вставить("Товар_Наименование", Выборка.Товар_Наименование);
		СтруктураСтроки.Вставить("Остаток",            Выборка.Остаток);

		СписокДанных.Добавить(СтруктураСтроки);
	КонецЦикла;

	// Запись в файл JSON
	ЗаписьJSON = Новый ЗаписьJSON;
	ПараметрыЗаписиJSON = Новый ПараметрыЗаписиJSON(,, Символы.Таб); // С отступами для читаемости

	Попытка
		ЗаписьJSON.ОткрытьФайл(ФайлJson,,, ПараметрыЗаписиJSON);
		ЗаписатьJSON(ЗаписьJSON, СписокДанных);
		ЗаписьJSON.Закрыть();
		Возврат Истина;
	Исключение
		// Обработка ошибки доступа к файлу или записи
		ЗаписьJSON.Закрыть();
		ЗаписатьЛогСобытий("Ошибка при записи JSON: " + ОписаниеОшибки(), УровеньЖурналаРегистрации.Ошибка);
		Возврат Ложь;
	КонецПопытки;

КонецФункции

// Функция выбирает строки из таблицы значений по фильтру склада и части наименования товара.
//
// Параметры:
//  Таблица      - ТаблицаЗначений - исходная таблица с данными.
//  Склад        - СправочникСсылка.Склады - склад для фильтрации.
//  Наименование - Строка - подстрока для поиска в наименовании товара.
//
// Возвращаемое значение:
//  ТаблицаЗначений - отфильтрованная таблица.
//
Функция ВыбратьСтрокиТаблицы(Таблица, Склад, Наименование) Экспорт

	Запрос = Новый Запрос;

	// Передаем таблицу значений в качестве параметра запроса.
	// Для этого она должна быть типизирована (иметь описание типов колонок).
	Запрос.УстановитьПараметр("ВнешняяТаблица", Таблица);
	Запрос.УстановитьПараметр("Склад", Склад);
	// Добавляем символы "%" для поиска подстроки в любом месте наименования.
	Запрос.УстановитьПараметр("Наименование", "%" + Наименование + "%");

	Запрос.Текст = 
	"ВЫБРАТЬ
	|	ВТ.Склад КАК Склад,
	|	ВТ.Товар КАК Товар,
	|	ВТ.Количество КАК Количество
	|ПОМЕСТИТЬ ВТ_Данные
	|ИЗ
	|	&ВнешняяТаблица КАК ВТ
	|;
	|
	|////////////////////////////////////////////////////////////////////////////////
	|ВЫБРАТЬ
	|	ВТ_Данные.Склад КАК Склад,
	|	ВТ_Данные.Товар КАК Товар,
	|	ВТ_Данные.Количество КАК Количество
	|ИЗ
	|	ВТ_Данные КАК ВТ_Данные
	|ГДЕ
	|	ВТ_Данные.Склад = &Склад
	|	И ВТ_Данные.Товар.Наименование ПОДОБНО &Наименование";

	РезультатЗапроса = Запрос.Выполнить();

	Если Не РезультатЗапроса.Пустой() Тогда
		Возврат РезультатЗапроса.Выгрузить();
	Иначе
		// Возвращаем пустую копию структуры таблицы, если ничего не найдено
		Возврат Таблица.СкопироватьКолонки();
	КонецЕсли;

КонецФункции

// Функция возвращает таблицу значений с товарами, которые были в наличии на Дата1,
// но полностью отсутствуют на складах на Дата2.
Функция УшедшийТовар(Дата1, Дата2) Экспорт

	Запрос = Новый Запрос;

	// Используем параметры для передачи дат в виртуальные таблицы
	Запрос.УстановитьПараметр("Дата1", Дата1);
	Запрос.УстановитьПараметр("Дата2", Дата2);

	Запрос.Текст = 
	"ВЫБРАТЬ
	|	ОстаткиНаДату1.Товар КАК Товар,
	|	СУММА(ОстаткиНаДату1.КоличествоОстаток) КАК Количество
	|ИЗ
	|	РегистрНакопления.ТоварныеЗапасы.Остатки(&Дата1, ) КАК ОстаткиНаДату1
	|		ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.ТоварныеЗапасы.Остатки(&Дата2, ) КАК ОстаткиНаДату2
	|		ПО ОстаткиНаДату1.Товар = ОстаткиНаДату2.Товар
	|ГДЕ
	|	ЕСТЬNULL(ОстаткиНаДату2.КоличествоОстаток, 0) <= 0
	|
	|СГРУППИРОВАТЬ ПО
	|	ОстаткиНаДату1.Товар";

	РезультатЗапроса = Запрос.Выполнить();

	Если Не РезультатЗапроса.Пустой() Тогда
		Возврат РезультатЗапроса.Выгрузить();
	Иначе
		// Возвращаем пустую таблицу с нужной структурой, если данных нет
		ТаблицаРезультат = Новый ТаблицаЗначений;
		ТаблицаРезультат.Колонки.Добавить("Товар", Новый ОписаниеТипов("СправочникСсылка.Товары"));
		ТаблицаРезультат.Колонки.Добавить("Количество", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(10, 2)));
		Возврат ТаблицаРезультат;
	КонецЕсли;

КонецФункции

// Функция возвращает таблицу значений с просроченными долгами контрагентов.
// Параметры:
//  Дата - Дата, на которую проверяется задолженность.
//  МинДолг - Число, минимальная сумма общего долга.
//  СрокДолга - Число, количество дней, после которых долг считается просроченным.
Функция ПросроченныеДолги(Дата, МинДолг, СрокДолга) Экспорт

	Запрос = Новый Запрос;

	// Вычисляем граничную дату, ранее которой долг считается просроченным
	ДатаГраницы = НачалоДня(Дата) - (СрокДолга * 24 * 60 * 60);

	Запрос.УстановитьПараметр("ДатаАнализа", КонецДня(Дата));
	Запрос.УстановитьПараметр("ДатаГраницы", ДатаГраницы);
	Запрос.УстановитьПараметр("МинДолг", МинДолг);

	Запрос.Текст = 
	"ВЫБРАТЬ
	|	ВзаиморасчетыОстатки.Контрагент КАК Контрагент,
	|	ВзаиморасчетыОстатки.СуммаОстаток КАК ДолгВсего
	|ПОМЕСТИТЬ ВТ_ОбщиеОстатки
	|ИЗ
	|	РегистрНакопления.Взаиморасчеты.Остатки(&ДатаАнализа, ) КАК ВзаиморасчетыОстатки
	|ГДЕ
	|	ВзаиморасчетыОстатки.СуммаОстаток > &МинДолг
	|;
	|
	|////////////////////////////////////////////////////////////////////////////////
	|ВЫБРАТЬ
	|	ВТ_ОбщиеОстатки.Контрагент КАК Контрагент,
	|	ВТ_ОбщиеОстатки.ДолгВсего КАК ДолгВсего,
	|	ВзаиморасчетыОстаткиИОбороты.СуммаНачальныйОстаток КАК ДолгПросроченный,
	|	ВзаиморасчетыОстаткиИОбороты.Период КАК ДатаОбразованияДолга
	|ИЗ
	|	ВТ_ОбщиеОстатки КАК ВТ_ОбщиеОстатки
	|		ВНУТРЕННЕЕ СОЕДИНЕНИЕ РегистрНакопления.Взаиморасчеты.ОстаткиИОбороты(, &ДатаГраницы, День, , ) КАК ВзаиморасчетыОстаткиИОбороты
	|		ПО ВТ_ОбщиеОстатки.Контрагент = ВзаиморасчетыОстаткиИОбороты.Контрагент
	|ГДЕ
	|	ВзаиморасчетыОстаткиИОбороты.СуммаКонечныйОстаток > 0
	|
	|УПОРЯДОЧИТЬ ПО
	|	ДатаОбразованияДолга ВОЗР
	|ИТОГИ
	|	МАКСИМУМ(ДолгВсего),
	|	СУММА(ДолгПросроченный),
	|	МИНИМУМ(ДатаОбразованияДолга)
	|ПО
	|	Контрагент";

	РезультатЗапроса = Запрос.Выполнить();

	// Подготовим таблицу значений для возврата
	ТаблицаРезультат = Новый ТаблицаЗначений;
	ТаблицаРезультат.Колонки.Добавить("Контрагент", Новый ОписаниеТипов("Справочник.Контрагенты"));
	ТаблицаРезультат.Колонки.Добавить("ДолгВсего", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));
	ТаблицаРезультат.Колонки.Добавить("ДолгПросроченный", Новый ОписаниеТипов("Число", Новый КвалификаторыЧисла(15, 2)));
	ТаблицаРезультат.Колонки.Добавить("ДатаОбразованияДолга", Новый ОписаниеТипов("Дата"));

	ВыборкаКонтрагент = РезультатЗапроса.Выбрать(ОбходРезультатаЗапроса.ПоГруппировкам);

	Пока ВыборкаКонтрагент.Следующий() Цикл
		// Нас интересуют только те, у кого просроченный долг (остаток на ДатуГраницы) > 0
		Если ВыборкаКонтрагент.ДолгПросроченный > 0 Тогда
			НоваяСтрока = ТаблицаРезультат.Добавить();
			НоваяСтрока.Контрагент = ВыборкаКонтрагент.Контрагент;
			НоваяСтрока.ДолгВсего = ВыборкаКонтрагент.ДолгВсего;
			НоваяСтрока.ДолгПросроченный = ВыборкаКонтрагент.ДолгПросроченный;
			НоваяСтрока.ДатаОбразованияДолга = ВыборкаКонтрагент.ДатаОбразованияДолга;
		КонецЕсли;
	КонецЦикла;

	Возврат ТаблицаРезультат;

КонецФункции

// Функция создает объект ИнтернетПочтовоеСообщение на основании данных справочника ИсходящиеПисьма.
//
// Параметры:
//  Письмо      - СправочникСсылка.ИсходящиеПисьма - Ссылка на документ-источник.
//  Отправитель - Строка - Email адрес отправителя.
//
// Возвращаемое значение:
//  ИнтернетПочтовоеСообщение - Сформированное сообщение.
//
Функция СоздатьИнтернетПочтовоеСообщение(Письмо, Отправитель) Экспорт

	Сообщение = Новый ИнтернетПочтовоеСообщение;

	// Установка основных реквизитов сообщения
	Сообщение.ИмяОтправителя  = Отправитель;
	Сообщение.Отправитель.Адрес = Отправитель;
	Сообщение.Тема            = Строка(Письмо); // Используем представление объекта как тему, если нет отдельного реквизита

	// Получаем данные письма и список получателей из табличной части
	Запрос = Новый Запрос;
	Запрос.Текст = 
	"ВЫБРАТЬ
	|	ИсходящиеПисьма.Текст КАК Текст,
	|	ИсходящиеПисьма.Получатели.(
	|		ЭлектроннаяПочта КАК ЭлектроннаяПочта
	|	) КАК ТаблицаПолучателей
	|ИЗ
	|	Справочник.ИсходящиеПисьма КАК ИсходящиеПисьма
	|ГДЕ
	|	ИсходящиеПисьма.Ссылка = &Ссылка";

	Запрос.УстановитьПараметр("Ссылка", Письмо);

	Выборка = Запрос.Выполнить().Выбрать();

	Если Выборка.Следующий() Тогда

		// Заполнение текста письма
		ТекстСообщения = Сообщение.Тексты.Добавить();
		ТекстСообщения.Текст = Выборка.Текст;
		ТекстСообщения.ТипТекста = ТипТекстаПочтовогоСообщения.ПростойТекст;

		// Заполнение списка получателей из табличной части
		ВыборкаПолучателей = Выборка.ТаблицаПолучателей.Выбрать();
		Пока ВыборкаПолучателей.Следующий() Цикл

			АдресПочты = СокращеннаяЛП(ВыборкаПолучателей.ЭлектроннаяПочта);
			Если Не ПустаяСтрока(АдресПочты) Тогда
				НовыйПолучатель = Сообщение.Получатели.Добавить(АдресПочты);
			КонецЕсли;

		КонецЦикла;

	КонецЕсли;

	Возврат Сообщение;

КонецФункции

// Функция создает движения по регистру накопления "Продажи" на основании данных документа.
// Параметры:
//  ДокументСсылка - ДокументСсылка.РасходТовара - ссылка на документ, по которому нужно создать движения.
Процедура СоздатьДвиженияРегистраПродажи(ДокументСсылка) Экспорт

	// 1. Очищаем старые движения документа по регистру "Продажи"
	НаборЗаписей = РегистрыНакопления.Продажи.СоздатьНаборЗаписей();
	НаборЗаписей.Отбор.Регистратор.Установить(ДокументСсылка);
	НаборЗаписей.Записать(); // Записываем пустой набор для удаления существующих записей

	// 2. Получаем данные из табличной части документа с помощью запроса
	Запрос = Новый Запрос;
	Запрос.Текст = 
	"ВЫБРАТЬ
	|	РасходТовараТовары.Номенклатура КАК Номенклатура,
	|	РасходТовараТовары.Количество КАК Количество,
	|	РасходТовараТовары.Сумма КАК Сумма,
	|	РасходТовара.Дата КАК Период,
	|	РасходТовара.Контрагент КАК Контрагент
	|ИЗ
	|	Документ.РасходТовара.Товары КАК РасходТовараТовары
	|		ЛЕВОЕ СОЕДИНЕНИЕ Документ.РасходТовара КАК РасходТовара
	|		ПО РасходТовараТовары.Ссылка = РасходТовара.Ссылка
	|ГДЕ
	|	РасходТовара.Ссылка = &ДокументСсылка";

	Запрос.УстановитьПараметр("ДокументСсылка", ДокументСсылка);

	РезультатЗапроса = Запрос.Выполнить();

	Если РезультатЗапроса.Пустой() Тогда
		Возврат;
	КонецЕсли;

	Выборка = РезультатЗапроса.Выбрать();

	// 3. Формируем новые движения
	Пока Выборка.Следующий() Цикл
		Движение = НаборЗаписей.Добавить();

		// Стандартные реквизиты
		Движение.ВидДвижения = ВидДвиженияНакопления.Приход;
		Движение.Период      = Выборка.Период;
		Движение.Регистратор = ДокументСсылка;

		// Измерения и ресурсы (согласно структуре регистра Продажи)
		Движение.Номенклатура = Выборка.Номенклатура;
		Движение.Контрагент   = Выборка.Контрагент;
		Движение.Количество   = Выборка.Количество;
		Движение.Сумма        = Выборка.Сумма;
	КонецЦикла;

	// 4. Записываем сформированный набор записей
	Если НаборЗаписей.Количество() > 0 Тогда
		НаборЗаписей.Записать(Ложь); // Ложь - значит не замещать (хотя мы уже очистили набор выше)
	КонецЕсли;

КонецПроцедуры

// Функция производит замену одной номенклатуры на другую в документах "Заказ"
// за указанный период.
//
// Параметры:
//  НоменклатураИсточник - СправочникСсылка.Товары - что ищем
//  НоменклатураЗамены   - СправочникСсылка.Товары - на что меняем
//  ДатаС                - Дата - начало периода поиска
//  ДатаПо               - Дата - конец периода поиска
//
Процедура ЗаменитьНоменклатуру(НоменклатураИсточник, НоменклатураЗамены, ДатаС, ДатаПо) Экспорт

	Запрос = Новый Запрос;
	Запрос.Текст = 
	"ВЫБРАТЬ
	|	Заказ.Ссылка КАК Ссылка,
	|	Заказ.Проведен КАК Проведен
	|ИЗ
	|	Документ.Заказ КАК Заказ
	|ГДЕ
	|	Заказ.Дата МЕЖДУ &ДатаС И &ДатаПо
	|	И НЕ Заказ.ПометкаУдаления
	|	И Заказ.Товары.Товар = &НоменклатураИсточник
	|
	|СГРУППИРОВАТЬ ПО
	|	Заказ.Ссылка,
	|	Заказ.Проведен";

	Запрос.УстановитьПараметр("ДатаС", ДатаС);
	Запрос.УстановитьПараметр("ДатаПо", КонецДня(ДатаПо));
	Запрос.УстановитьПараметр("НоменклатураИсточник", НоменклатураИсточник);

	Выборка = Запрос.Выполнить().Выбрать();

	Пока Выборка.Следующий() Цикл

		ОбъектДокумента = Выборка.Ссылка.ПолучитьОбъект();
		БылИзменен = Ложь;

		// Обходим табличную часть и ищем совпадения
		Для Каждого СтрокаТовара Из ОбъектДокумента.Товары Цикл
			Если СтрокаТовара.Товар = НоменклатураИсточник Тогда
				СтрокаТовара.Товар = НоменклатураЗамены;
				БылИзменен = Истина;
			КонецЕсли;
		КонецЦикла;

		Если БылИзменен Тогда
			Попытка
				// Если документ был проведен, перепроводим его. 
				// Если был просто записан - сохраняем без проведения.
				РежимЗаписи = ?(Выборка.Проведен, РежимЗаписиДокумента.Проведение, РежимЗаписиДокумента.Запись);
				ОбъектДокумента.Записать(РежимЗаписи);
			Исключение
				ОбщегоНазначенияКлиентСервер.СообщитьПользователю(
					НСтр("ru = 'Ошибка при записи документа " + Выборка.Ссылка + ": " + ОписаниеОшибки() + "'")
				);
			КонецПопытки;
		КонецЕсли;

	КонецЦикла;

КонецПроцедуры

// Функция рассчитывает комиссию менеджеров на основе проведенных заказов
// Параметры:
//  ТаблицаКомиссий - ТаблицаЗначений, которую необходимо заполнить (колонки: Менеджер, СуммаЗаказов, Комиссия)
//  Процент         - Число, процент комиссии (например, 5)
//  ДатаС           - Дата, начало периода
//  ДатаПо          - Дата, конец периода
//
Процедура РасчетКомиссииМенеджера(ТаблицаКомиссий, Процент, ДатаС, ДатаПо) Экспорт

	// Очищаем таблицу перед заполнением
	ТаблицаКомиссий.Очистить();

	Запрос = Новый Запрос;
	Запрос.Текст = 
	"ВЫБРАТЬ
	|	ЗаказТовары.Ссылка.Автор КАК Менеджер,
	|	СУММА(ЗаказТовары.Сумма) КАК СуммаЗаказов,
	|	СУММА(ЗаказТовары.Сумма) * &Процент / 100 КАК Комиссия
	|ИЗ
	|	Документ.Заказ.Товары КАК ЗаказТовары
	|ГДЕ
	|	ЗаказТовары.Ссылка.Проведен = ИСТИНА
	|	И ЗаказТовары.Ссылка.Дата МЕЖДУ &ДатаС И &ДатаПо
	|СГРУППИРОВАТЬ ПО
	|	ЗаказТовары.Ссылка.Автор";

	Запрос.УстановитьПараметр("ДатаС", НачалоДня(ДатаС));
	Запрос.УстановитьПараметр("ДатаПо", КонецДня(ДатаПо));
	Запрос.УстановитьПараметр("Процент", Процент);

	РезультатЗапроса = Запрос.Выполнить();

	// Если результат не пустой, выгружаем данные в таблицу
	Если Не РезультатЗапроса.Пустой() Тогда
		ТаблицаКомиссий = РезультатЗапроса.Выгрузить();
	КонецЕсли;

КонецПроцедуры

// Функция считывает JPEG файл и возвращает структуру с его размерами.
// Параметры:
//  ИмяФайла - Строка - Полный путь к файлу на диске.
// Возвращаемое значение:
//  Структура - {"Высота": Число, "Ширина": Число}
//
Функция ПолучитьШиринуВысотуКартинкиИзФайлаJPEG(ИмяФайла) Экспорт

	Результат = Новый Структура;
	Результат.Вставить("Высота", 0);
	Результат.Вставить("Ширина", 0);

	ФайлНаДиске = Новый Файл(ИмяФайла);
	Если Не ФайлНаДиске.Существует() Тогда
		Возврат Результат;
	КонецЕсли;

	Попытка
		// Читаем файл в объект Картинка
		ОбъектКартинка = Новый Картинка(ИмяФайла);

		// Получаем параметры
		Результат.Высота = ОбъектКартинка.Высота();
		Результат.Ширина = ОбъектКартинка.Ширина();
	Исключение
		// В случае ошибки (например, файл не является картинкой)
		// можно записать событие в журнал регистрации
		ЗаписьЖурналаРегистрации("ЧтениеКартинки", УровеньЖурналаРегистрации.Ошибка, , , 
			"Ошибка при получении размеров файла: " + ИмяФайла + Символы.ПС + ОписаниеОшибки());
	КонецПопытки;

	Возврат Результат;

КонецФункции

// Функция извлекает партии по методу ФИФО на заданную сумму
// Параметры:
//  ТаблицаПартий - ТаблицаЗначений: "Партия", "Дата", "Сумма"
//  СуммаДляИзвлечения - Число: требуемая сумма
// Возвращаемое значение:
//  ТаблицаЗначений: подобранные партии
Функция ИзвлечьПартииФИФО(ТаблицаПартий, Знач СуммаДляИзвлечения) Экспорт

	// Подготовим таблицу для результата
	ТаблицаРезультат = ТаблицаПартий.СкопироватьКолонки();

	Если СуммаДляИзвлечения <= 0 Тогда
		Возврат ТаблицаРезультат;
	КонецЕсли;

	// Используем запрос для эффективной сортировки таблицы значений
	Запрос = Новый Запрос;
	Запрос.УстановитьПараметр("ТЗ", ТаблицаПартий);
	Запрос.Текст = 
	"ВЫБРАТЬ
	|	ТЗ.Партия КАК Партия,
	|	ТЗ.Дата КАК Дата,
	|	ТЗ.Сумма КАК Сумма
	|ПОМЕСТИТЬ ВТ_Партии
	|ИЗ
	|	&ТЗ КАК ТЗ
	|;
	|
	|////////////////////////////////////////////////////////////////////////////////
	|ВЫБРАТЬ
	|	ВТ_Партии.Партия КАК Партия,
	|	ВТ_Партии.Дата КАК Дата,
	|	ВТ_Партии.Сумма КАК Сумма
	|ИЗ
	|	ВТ_Партии КАК ВТ_Партии
	|
	|УПОРЯДОЧИТЬ ПО
	|	Дата";

	Выборка = Запрос.Выполнить().Выбрать();

	ОсталосьРаспределить = СуммаДляИзвлечения;

	Пока Выборка.Следующий() И ОсталосьРаспределить > 0 Цикл

		СуммаПартии = Выборка.Сумма;

		// Если сумма в текущей партии больше, чем нам осталось добрать
		Если СуммаПартии > ОсталосьРаспределить Тогда
			СуммаПартии = ОсталосьРаспределить;
		КонецЕсли;

		// Добавляем строку в результат
		НоваяСтрока = ТаблицаРезультат.Добавить();
		ЗаполнитьЗначенияСвойств(НоваяСтрока, Выборка);
		НоваяСтрока.Сумма = СуммаПартии;

		ОсталосьРаспределить = ОсталосьРаспределить - СуммаПартии;

	КонецЦикла;

	Возврат ТаблицаРезультат;

КонецФункции

// Функция дополняет первую таблицу значений данными из второй.
// Новые данные добавляются в начало таблицы.
// Уникальность контролируется по указанной колонке.
//
// Параметры:
//  Таблица1 - ТаблицаЗначений - Таблица, в которую добавляются данные
//  Таблица2 - ТаблицаЗначений - Таблица, из которой берутся данные
//  КолонкаУникальности - Строка - Имя колонки для проверки уникальности
//
// Возвращаемое значение:
//  ТаблицаЗначений - Результирующая таблица
//
Функция ДополнитьТаблицуЗначениямиИзВторой(Таблица1, Таблица2, КолонкаУникальности) Экспорт

	// Если вторая таблица пуста, возвращаем первую без изменений
	Если Таблица2.Количество() = 0 Тогда
		Возврат Таблица1;
	КонецЕсли;

	// Если первая таблица пуста, просто возвращаем копию второй
	Если Таблица1.Количество() = 0 Тогда
		Возврат Таблица2.Скопировать();
	КонецЕсли;

	Запрос = Новый Запрос;
	МенеджерВТ = Новый МенеджерВременныхТаблиц;
	Запрос.МенеджерВременныхТаблиц = МенеджерВТ;

	// Помещаем первую таблицу во временную таблицу
	Запрос.Текст = 
	"ВЫБРАТЬ
	|	ТЗ1.*
	|ПОМЕСТИТЬ ВТ_Таблица1
	|ИЗ
	|	&Таблица1 КАК ТЗ1";
	Запрос.УстановитьПараметр("Таблица1", Таблица1);
	Запрос.Выполнить();

	// Помещаем вторую таблицу во временную таблицу
	Запрос.Текст = 
	"ВЫБРАТЬ
	|	ТЗ2.*
	|ПОМЕСТИТЬ ВТ_Таблица2
	|ИЗ
	|	&Таблица2 КАК ТЗ2";
	Запрос.УстановитьПараметр("Таблица2", Таблица2);
	Запрос.Выполнить();

	// Основной запрос: 
	// 1. Выбираем записи из ТЗ2, которых нет в ТЗ1 (обеспечение уникальности)
	// 2. Объединяем с записями из ТЗ1
	// Используем ОБЪЕДИНИТЬ ВСЕ, так как уникальность внутри ТЗ2 не гарантирована условием,
	// но если нужно исключить дубли и внутри ТЗ2, можно добавить СГРУППИРОВАТЬ.

	// Формируем текст запроса динамически, чтобы сохранить порядок (ТЗ2 в начале)
	Запрос.Текст = 
	"ВЫБРАТЬ
	|	ТЗ2.*
	|ИЗ
	|	ВТ_Таблица2 КАК ТЗ2
	|ГДЕ
	|	НЕ ТЗ2." + КолонкаУникальности + " В (ВЫБРАТЬ Т1." + КолонкаУникальности + " ИЗ ВТ_Таблица1 КАК Т1)
	|
	|ОБЪЕДИНИТЬ ВСЕ
	|
	|ВЫБРАТЬ
	|	ТЗ1.*
	|ИЗ
	|	ВТ_Таблица1 КАК ТЗ1";

	РезультатЗапроса = Запрос.Выполнить();

	Если РезультатЗапроса.Пустой() Тогда
		Возврат Таблица1.СкопироватьКолонки();
	КонецЕсли;

	Возврат РезультатЗапроса.Выгрузить();

КонецФункции

